p=ROOT+'/content/curriculum/cbse-2026-27.json'; d=json.load(open(p)); c=[x for x in d['classes'] if x['classLevel']==5][0]
if not any(s['slug']==S for s in c['subjects']):
    ev=[s for s in c['subjects'] if s['slug']=='evs'][0]
    tmpl=copy.deepcopy(ev['chapters'][0]['topics'][0])
    def topic(slug,name,obj):
        t=copy.deepcopy(tmpl); t['slug']=slug; t['name']={"en":name}; t['objectives']=[{"text":{"en":obj}}]
        for k in list(t.keys()):
            pass
        return t
    chs=[("warm-up-and-cool-down","Warm-up and Cool-down","warm-up-exercises","Warm-up exercises","Do warm-up and cool-down movements safely"),
     ("throwing-and-catching","Throwing and Catching","throwing-and-catching-skills","Throwing and catching skills","Throw and catch with correct grip and follow-through"),
     ("kicking-and-receiving","Kicking and Receiving","kicking-and-receiving-skills","Kicking and receiving skills","Kick and receive a ball with the foot"),
     ("strike-the-object","Strike the Object","striking-with-a-bat-or-racquet","Striking with a bat or racquet","Strike and receive an object with a racquet"),
     ("little-steps","Little Steps","setting-and-achieving-goals","Setting and achieving goals","Set small fitness goals and balance and strength"),
     ("local-and-traditional-games","Local and Traditional Games","why-traditional-games-matter","Why traditional games matter","Know India's traditional games and their values"),
     ("yoga-for-daily-life","Yoga for Daily Life","paths-of-yoga-and-ashtanga","Paths of yoga and Ashtanga","Name the paths of yoga and the eight limbs"),
     ("yoga-sadhana","Yoga Sadhana","asanas-pranayama-and-mudras","Asanas, pranayama and mudras","Know the practices in Yoga Sadhana")]
    sub={"slug":S,"name":{"en":"Physical Education and Well-being (Khel Yoga)"},"textbook":{"title":"Khel Yoga","publisher":"NCERT","edition":"2026-27","sourceRef":"https://ncert.nic.in/textbook.php"},
      "chapters":[{"slug":a,"name":{"en":b},"topics":[topic(ts,tn,ob)]} for a,b,ts,tn,ob in chs]}
    c['subjects'].append(sub); json.dump(d,open(p,'w'),indent=2,ensure_ascii=False)
